 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    bars = []  # (orientation, side, start, end, color), end exclusive

    # Detect contiguous non-background runs attached to the four boundaries.
    for r, side in ((0, "top"), (h - 1, "bottom")):
        c = 0
        while c < w:
            color = grid[r][c]
            end = c + 1
            while end < w and grid[r][end] == color:
                end += 1
            if color != background and end - c >= 2:
                bars.append(("horizontal", side, c, end, color))
            c = end
    for c, side in ((0, "left"), (w - 1, "right")):
        r = 0
        while r < h:
            color = grid[r][c]
            end = r + 1
            while end < h and grid[end][c] == color:
                end += 1
            if color != background and end - r >= 2:
                bars.append(("vertical", side, r, end, color))
            r = end

    bar_cells = set()
    for orient, side, start, end, _ in bars:
        if side == "top":
            bar_cells.update((0, c) for c in range(start, end))
        elif side == "bottom":
            bar_cells.update((h - 1, c) for c in range(start, end))
        elif side == "left":
            bar_cells.update((r, 0) for r in range(start, end))
        else:
            bar_cells.update((r, w - 1) for r in range(start, end))

    # The isolated non-background color is the ray/marker color.
    color_counts = Counter(
        grid[r][c]
        for r in range(h) for c in range(w)
        if grid[r][c] != background and (r, c) not in bar_cells
    )
    if not bars or not color_counts:
        return [row[:] for row in grid]
    marker = color_counts.most_common(1)[0][0]
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker and (r, c) not in bar_cells]

    # A bar overlapping marker coordinates identifies the motif's offsets.
    # These offsets are repeated from the start of every parallel bar.
    ref = max(
        bars,
        key=lambda bar: sum(
            bar[2] <= (c if bar[0] == "horizontal" else r) < bar[3]
            for r, c in markers
        ),
    )
    orientation, _, ref_start, ref_end, _ = ref
    offsets = sorted({
        (c if orientation == "horizontal" else r) - ref_start
        for r, c in markers
        if ref_start <= (c if orientation == "horizontal" else r) < ref_end
    })

    out = [row[:] for row in grid]
    for orient, side, start, end, _ in bars:
        if orient != orientation:
            continue
        for offset in offsets:
            pos = start + offset
            if not start <= pos < end:
                continue
            if side == "top":
                r, c, dr, dc = 1, pos, 1, 0
            elif side == "bottom":
                r, c, dr, dc = h - 2, pos, -1, 0
            elif side == "left":
                r, c, dr, dc = pos, 1, 0, 1
            else:  # right
                r, c, dr, dc = pos, w - 2, 0, -1

            while 0 <= r < h and 0 <= c < w:
                if grid[r][c] == marker:
                    out[r][c] = 4
                    break
                if grid[r][c] == background:
                    out[r][c] = marker
                r += dr
                c += dc
    return out
