    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Border bars: (side, axis_start, axis_end, color), with end exclusive.
    bars = []
    for r, side in ((0, "top"), (h - 1, "bottom")):
        c = 0
        while c < w:
            color = grid[r][c]
            end = c + 1
            while end < w and grid[r][end] == color:
                end += 1
            if color != background and end - c >= 2:
                bars.append((side, c, end, color))
            c = end
    for c, side in ((0, "left"), (w - 1, "right")):
        r = 0
        while r < h:
            color = grid[r][c]
            end = r + 1
            while end < h and grid[end][c] == color:
                end += 1
            if color != background and end - r >= 2:
                bars.append((side, r, end, color))
            r = end

    bar_cells = set()
    for side, start, end, _ in bars:
        if side == "top":
            bar_cells.update((0, c) for c in range(start, end))
        elif side == "bottom":
            bar_cells.update((h - 1, c) for c in range(start, end))
        elif side == "left":
            bar_cells.update((r, 0) for r in range(start, end))
        else:
            bar_cells.update((r, w - 1) for r in range(start, end))

    # The isolated non-background objects supply ray offsets and ray color.
    color_counts = Counter(
        grid[r][c]
        for r in range(h) for c in range(w)
        if grid[r][c] != background and (r, c) not in bar_cells
    )
    if not color_counts or not bars:
        return [row[:] for row in grid]
    ray_color = color_counts.most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == ray_color and (r, c) not in bar_cells]

    # Find the bar on which the marker pattern is placed. Transfer its offsets
    # from the bar's start to every bar with the same orientation.
    def axis_coord(side, point):
        r, c = point
        return c if side in ("top", "bottom") else r

    reference = max(
        bars,
        key=lambda bar: sum(bar[1] <= axis_coord(bar[0], p) < bar[2]
                            for p in points),
    )
    ref_side, ref_start, ref_end, _ = reference
    horizontal = ref_side in ("top", "bottom")
    offsets = sorted({axis_coord(ref_side, p) - ref_start for p in points
                      if ref_start <= axis_coord(ref_side, p) < ref_end})

    out = [row[:] for row in grid]
    for side, start, end, _ in bars:
        if (side in ("top", "bottom")) != horizontal:
            continue
        for offset in offsets:
            pos = start + offset
            if not start <= pos < end:
                continue
            if side == "top":
                r, c, dr, dc = 1, pos, 1, 0
            elif side == "bottom":
                r, c, dr, dc = h - 2, pos, -1, 0
            elif side == "left":
                r, c, dr, dc = pos, 1, 0, 1
            else:  # right
                r, c, dr, dc = pos, w - 2, 0, -1

            while 0 <= r < h and 0 <= c < w:
                if grid[r][c] == ray_color:
                    out[r][c] = 4
                    break
                if grid[r][c] == background:
