    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find colored runs on the four borders.
    bars = []  # side, start, end (exclusive), color
    for r, side in ((0, 'top'), (h - 1, 'bottom')):
        c = 0
        while c < w:
            color = grid[r][c]
            end = c + 1
            while end < w and grid[r][end] == color:
                end += 1
            if color != background and end - c >= 2:
                bars.append((side, c, end, color))
            c = end
    for c, side in ((0, 'left'), (w - 1, 'right')):
        r = 0
        while r < h:
            color = grid[r][c]
            end = r + 1
            while end < h and grid[end][c] == color:
                end += 1
            if color != background and end - r >= 2:
                bars.append((side, r, end, color))
            r = end

    bar_cells = set()
    for side, start, end, _ in bars:
        if side == 'top':
            bar_cells.update((0, c) for c in range(start, end))
        elif side == 'bottom':
            bar_cells.update((h - 1, c) for c in range(start, end))
        elif side == 'left':
            bar_cells.update((r, 0) for r in range(start, end))
        else:
            bar_cells.update((r, w - 1) for r in range(start, end))

    # Identify the marker color, excluding the background and edge bars.
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != background and (r, c) not in bar_cells)
    if not bars or not counts:
        return [row[:] for row in grid]
    marker = counts.most_common(1)[0][0]
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker and (r, c) not in bar_cells]

    # Copy marker coordinates relative to their minimum axis coordinate onto
    # each edge bar, then project inward until the first marker collision.
    min_row = min(r for r, _ in markers)
    min_col = min(c for _, c in markers)
    out = [row[:] for row in grid]
    for side, start, end, _ in bars:
        if side in ('top', 'bottom'):
            active = sorted({start + c - min_col for _, c in markers})
            for c in active:
                if not start <= c < end:
                    continue
                r = 1 if side == 'top' else h - 2
                step = 1 if side == 'top' else -1
                while 0 <= r < h:
                    if grid[r][c] == marker:
                        out[r][c] = 4
